    private val months: Map<String, Pair<LocalDate, Int>> by lazy {
        val m = HashMap<String, Pair<LocalDate, Int>>()
        RAW.split(",").forEach { s ->
            val p = s.split(":")
            val d = p[2]
            m[p[0] + "-" + p[1]] = LocalDate.of(d.substring(0, 4).toInt(), d.substring(4, 6).toInt(), d.substring(6, 8).toInt()) to p[3].toInt()
        }
        m
    }
    fun has(y: Int) = y in 1950..2050
    // 음력 y년 m월 d일(평달) → 양력. 작은달이면 29일로
    fun solar(y: Int, m: Int, d: Int): LocalDate? {
        val v = months["$y-$m"] ?: return null
        return v.first.plusDays((minOf(d, v.second) - 1).toLong())
    }
    // 양력 y년 안에 있는 음력 m월 d일
    fun inYear(y: Int, m: Int, d: Int): List<LocalDate> =
        listOf(y - 1, y).mapNotNull { solar(it, m, d) }.filter { it.year == y }
}
